"use client";
import { useState, useEffect } from "react";
import { useParams } from "next/navigation";

export default function JobDetails() {
  const params = useParams();
  const jobId = params.id;

  const dummyJobs = [
    { id: "1", name: "Job One", customer: "Customer A", description: "Painting exterior", status: "Active", budget: 1000 },
    { id: "2", name: "Job Two", customer: "Customer B", description: "Interior renovation", status: "Completed", budget: 1500 },
    { id: "3", name: "Job Three", customer: "Customer C", description: "New build painting", status: "Quoted", budget: 2000 },
  ];

  const [job, setJob] = useState<any>(null);

  useEffect(() => {
    const foundJob = dummyJobs.find((j) => j.id === jobId);
    setJob(foundJob || null);
  }, [jobId]);

  if (!job) {
    return (
      <main style={{ padding: "2rem", textAlign: "left" }}>
        <h1>Job Not Found</h1>
        <p>No job found for ID: {jobId}</p>
      </main>
    );
  }

  return (
    <main style={{ padding: "2rem", textAlign: "left" }}>
      <h1>Job Details</h1>

      {Object.keys(job).map((key) => (
        <p key={key}>
          <strong>{key.charAt(0).toUpperCase() + key.slice(1)}:</strong> {job[key]}
        </p>
      ))}

      <div style={{ marginTop: "1rem" }}>
        <button style={{ marginRight: "0.5rem", padding: "0.5rem 1rem" }}>Edit Job Details</button>
        <button style={{ padding: "0.5rem 1rem" }}>Delete Job</button>
      </div>
    </main>
  );
}
